-- Account startup procedures. The procedure signatures and the routing to
-- database pool -1 match Cached.exe. Tables and bodies come from the original
-- lin2user database.

BEGIN;

CREATE SCHEMA IF NOT EXISTS "account";

CREATE TABLE "account"."del_account" (
    "request_date" timestamp without time zone NOT NULL,
    "del_date" timestamp without time zone DEFAULT "world"."mssql_getdate"() NOT NULL,
    "del_id" integer GENERATED BY DEFAULT AS IDENTITY
        (START WITH 8350 INCREMENT BY 1) NOT NULL,
    "account_id" integer NOT NULL,
    "seq" integer NOT NULL,
    CONSTRAINT "pk_del_account" PRIMARY KEY ("del_id")
);

CREATE TABLE "account"."del_world" (
    "world_id" integer NOT NULL,
    "del_id" integer,
    "update_date" timestamp without time zone DEFAULT "world"."mssql_getdate"(),
    CONSTRAINT "pk_del_world" PRIMARY KEY ("world_id")
);

-- Date subtraction matches MSSQL DATEDIFF(day, ..., GETDATE()).
-- at day boundaries. The deployment timezone therefore remains a compatibility input.
CREATE OR REPLACE FUNCTION "account"."lin_getdelaccountid"(
    p_world_id integer
) RETURNS TABLE (
    request_age_days integer,
    deletion_age_days integer,
    deletion_id integer,
    account_id integer,
    sequence integer
)
LANGUAGE sql
STABLE
AS $function$
    SELECT
        "world"."mssql_getdate"()::date - pending.request_date::date,
        "world"."mssql_getdate"()::date - pending.del_date::date,
        pending.del_id,
        pending.account_id,
        pending.seq
    FROM "account"."del_account" AS pending
    WHERE pending.del_id > COALESCE((
        SELECT progress.del_id
        FROM "account"."del_world" AS progress
        WHERE progress.world_id = p_world_id
    ), 0)
    ORDER BY pending.del_id;
$function$;

-- Atomic PostgreSQL replacement for the donor SELECT/@@ROWCOUNT/INSERT-or-UPDATE.
CREATE OR REPLACE FUNCTION "account"."lin_setdelid"(
    p_world_id integer,
    p_deletion_id integer
) RETURNS void
LANGUAGE sql
VOLATILE
AS $function$
    INSERT INTO "account"."del_world" (world_id, del_id, update_date)
    VALUES (p_world_id, p_deletion_id, "world"."mssql_getdate"())
    ON CONFLICT (world_id) DO UPDATE
    SET del_id = EXCLUDED.del_id,
        update_date = EXCLUDED.update_date;
$function$;

COMMIT;
